// Workspace chrome: local preferences and keyboard access, independent of project data.
export function initWorkbenchUI({getPref,setPref,onPresent=()=>{}}){
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],body=document.body;let widthBand='',drag=null,dialogOrigin=null;
 const memory=new Map(),collapsedGroups=new Set();
 const widths={library:{key:'parts-width',css:'--left',min:230,max:420,default:278},inspector:{key:'inspector-width',css:'--right',min:270,max:440,default:314}};
 function applyWidth(side,value,persist=false){const c=widths[side],other=side==='library'?'inspector':'library',otherWidth=Number($(`[data-resize-panel="${other}"]`).getAttribute('aria-valuenow'))||widths[other].default,max=innerWidth>1100?Math.min(c.max,innerWidth-(body.classList.contains('hide-'+other)?0:otherWidth)-280):c.max,n=Math.round(Math.max(c.min,Math.min(max,Number(value)||c.default)));document.documentElement.style.setProperty(c.css,n+'px');const handle=$(`[data-resize-panel="${side}"]`);handle.setAttribute('aria-valuenow',n);handle.setAttribute('aria-valuemax',Math.max(c.min,max));if(persist)setPref(c.key,String(n));return n;}
 for(const [side,c] of Object.entries(widths))applyWidth(side,getPref(c.key,c.default));
 function sync(){
  const focus=body.classList.contains('present');for(const [side,id] of [['library','toggleLibrary'],['inspector','toggleInspector']]){const open=!body.classList.contains('hide-'+side)&&!focus;$('#'+id).setAttribute('aria-expanded',open);$('#'+id).classList.toggle('active',open);$('#'+id).disabled=focus;}
  const overlay=innerWidth<=1100&&!focus&&(!body.classList.contains('hide-inspector')||(innerWidth<=720&&!body.classList.contains('hide-library')));$('#panelScrim').hidden=!overlay;
  $('#present').setAttribute('aria-pressed',focus);$('#present').textContent=focus?'Exit focus':'Focus view';$('#unitsLabel').textContent=$('#units').value==='in'?'Inches':'Millimeters';
  for(const b of $$('[data-tool],[data-shell]'))b.setAttribute('aria-pressed',b.classList.contains('active'));
 }
 function panel(side,show=true,{focus=false,persist=true}={}){if(body.classList.contains('present'))present(false);body.classList.toggle('hide-'+side,!show);if(innerWidth<=720&&show)body.classList.add('hide-'+(side==='library'?'inspector':'library'));if(innerWidth>1100&&show)applyWidth(side,Number($('[data-resize-panel="'+side+'"]').getAttribute('aria-valuenow')));if(innerWidth>1100&&persist)setPref(side+'-open',String(show));sync();if(focus&&show)(side==='library'?($('#libraryView').hidden?$('#assemblyList button')||$('#assemblyTab'):$('#search')):$('#inspectorContent input, #inspectorContent button'))?.focus();}
 function closePanels(){if(innerWidth<=720)panel('library',false,{persist:false});panel('inspector',false,{persist:false});}
 function present(on=!body.classList.contains('present')){body.classList.toggle('present',on);onPresent(on);sync();}
 function layout(){const band=innerWidth<=720?'phone':innerWidth<=1100?'tablet':'desktop';if(band!==widthBand){widthBand=band;body.classList.toggle('hide-library',band==='phone'||(band==='desktop'&&getPref('library-open','true')==='false'));body.classList.toggle('hide-inspector',band!=='desktop'||getPref('inspector-open','true')==='false');}if(band==='desktop')for(const [side,c] of Object.entries(widths))applyWidth(side,getPref(c.key,c.default));sync();}
 $('#toggleLibrary').onclick=()=>panel('library',body.classList.contains('hide-library'),{focus:true});$('#toggleInspector').onclick=()=>panel('inspector',body.classList.contains('hide-inspector'),{focus:true});
 for(const b of $$('[data-panel-close]'))b.onclick=()=>{const side=b.dataset.panelClose;panel(side,false);$('#'+(side==='library'?'toggleLibrary':'toggleInspector')).focus();};$('#panelScrim').onclick=closePanels;$('#present').onclick=()=>present();window.addEventListener('resize',layout);layout();
 function endDrag(){if(!drag)return;applyWidth(drag.side,drag.value,true);drag=null;body.classList.remove('panel-resizing');}
 for(const handle of $$('[data-resize-panel]')){const side=handle.dataset.resizePanel,c=widths[side];handle.onpointerdown=e=>{if(e.button!==0||innerWidth<=1100)return;e.preventDefault();drag={side,start:e.clientX,width:Number(handle.getAttribute('aria-valuenow')),value:Number(handle.getAttribute('aria-valuenow'))};handle.setPointerCapture?.(e.pointerId);body.classList.add('panel-resizing');};handle.onpointermove=e=>{if(!drag||drag.side!==side)return;drag.value=applyWidth(side,drag.width+(e.clientX-drag.start)*(side==='library'?1:-1));};handle.onpointerup=endDrag;handle.onpointercancel=endDrag;handle.ondblclick=()=>applyWidth(side,c.default,true);handle.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home'].includes(e.key))return;e.preventDefault();const value=e.key==='Home'?c.default:Number(handle.getAttribute('aria-valuenow'))+(e.key==='ArrowRight'?16:-16)*(side==='library'?1:-1);applyWidth(side,value,true);};}
 function decorateInspector(){for(const d of $$('#inspectorContent details')){const key=d.dataset.disclosure||d.querySelector('summary')?.textContent.trim();if(!key)continue;d.dataset.disclosure=key;if(memory.has(key))d.open=memory.get(key);d.ontoggle=()=>{if(d.isConnected)memory.set(key,d.open);};}for(const d of $$('#assemblyList [data-assembly-group]')){d.open=!collapsedGroups.has(d.dataset.assemblyGroup);d.ontoggle=()=>{if(!d.isConnected)return;d.open?collapsedGroups.delete(d.dataset.assemblyGroup):collapsedGroups.add(d.dataset.assemblyGroup);};}sync();}
 function closeMenus(except=null){for(const d of $$('details.menu[open]'))if(d!==except)d.open=false;}
 document.addEventListener('click',e=>{const summary=e.target.closest('details.menu>summary'),menu=e.target.closest('details.menu');if(summary)closeMenus(menu);else if(e.target.closest('details.menu button'))closeMenus();else if(!menu)closeMenus();});
 document.addEventListener('keydown',e=>{
  if(e.defaultPrevented)return;
  const tab=e.target.closest('[role=tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const all=[...tab.parentElement.querySelectorAll('[role=tab]')],i=all.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowRight'?1:-1)+all.length)%all.length;all[next].click();all[next].focus();return;}
  const menu=e.target.closest('details.menu');if(menu){const buttons=[...menu.querySelectorAll('button:not(:disabled),select')],summary=menu.querySelector('summary');if(e.key==='Escape'){e.preventDefault();menu.open=false;summary.focus();return;}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)&&e.target.tagName!=='SELECT'){e.preventDefault();menu.open=true;const i=buttons.indexOf(e.target);buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();return;}}
  if(e.key==='Escape'&&!$('#modal').open){if(body.classList.contains('present')){e.preventDefault();present(false);}else if(!$('#panelScrim').hidden){e.preventDefault();closePanels();$('#viewport').focus();}}
 });
 function beforeDialog(){const active=document.activeElement;if(!$('#modal').open&&active&&active!==body){dialogOrigin=active.closest('details.menu')?.querySelector('summary')||active;}closeMenus();}
 $('#modal').addEventListener('close',()=>{if(dialogOrigin?.isConnected)dialogOrigin.focus();dialogOrigin=null;});
 return {sync,panel,present,decorateInspector,beforeDialog};
}

export function exportHTML(){return `<p class="export-intro">Choose what your client or next tool needs.</p><section class="export-section"><div class="export-heading"><span class="eyebrow">01 / Present the idea</span><span>Images, motion & review</span></div><div class="export-grid"><button data-export="mp4" class="export-card export-featured"><span class="format-tag">MP4</span><strong>Product presentation</strong><small>Closed → transparent 360° → exploded 360° → studio finish.</small><span class="export-link">Create a movie <span aria-hidden="true">↗</span></span></button><button data-export="png" class="export-card"><span class="format-tag">PNG</span><strong>Client image</strong><small>A clean image of the current view, without editing handles.</small></button><button data-export="report" class="export-card"><span class="format-tag">PDF / PRINT</span><strong>Design review</strong><small>Assembly image, parts list, fit observations and evidence.</small></button><button data-export="glb" class="export-card"><span class="format-tag">GLB</span><strong>3D model & views</strong><small>Textured assembly with materials, decals and saved views.</small></button></div></section><section class="export-section"><div class="export-heading"><span class="eyebrow">02 / Build & source</span><span>Geometry & component records</span></div><div class="export-grid export-compact"><button data-export="drawings" class="export-card"><span class="format-tag">PDF · SVG · ZIP</span><strong>Engineering drawings</strong><small>Isometric + six dimensioned views, component details and dimension registers.</small></button><button data-export="fabrication" class="export-card"><span class="format-tag">STL · SVG · DXF</span><strong>Part & surface files</strong><small>Selected solid or nominal profiles.</small></button><button data-export="stl" class="export-card"><span class="format-tag">STL</span><strong>Concept assembly</strong><small>Separate component solids in mm. Not fabrication-ready.</small></button><button data-export="csv" class="export-card"><span class="format-tag">CSV</span><strong>Bill of materials</strong><small>Quantities, dimensions, sources and entered costs.</small></button></div></section><button data-export="json" class="export-backup"><span><strong>Keep an editable backup</strong><small>Project JSON includes your parts, models, decals and settings.</small></span><span class="format-tag">SAVE JSON ↗</span></button>`;}
